// "How to use KGuitar": a plain-language tour of every feature, for someone opening the app for the first time.
// Each item can jump straight to the feature it describes.
import type { Go } from './path'

export interface GuideItem { title: string; text: string; go?: Go; tip?: string; /** only in the phone app */ phoneOnly?: boolean }
export interface GuideSection { id: string; title: string; intro: string; items: GuideItem[] }

export const GUIDE: GuideSection[] = [
  {
    id: 'start', title: 'Start here', intro: 'KGuitar listens while you play a tab and lights up every note you get right. Around that it teaches you, trains your ear and keeps you practising every day. It works for guitar and ukulele.',
    items: [
      { title: 'Ask: search and the assistant in one', text: 'Tap Ask in the menu and type what you want in your own words. Short things ("G7", "drop D", "slow it down") open straight away. Bigger requests ("I want to practise triads today", "chord tones and soloing in A", "make me a trap beat at 140") make a practice session or set things up for you. It knows what\'s on your screen (the song, bar, loop, speed and chord in Play; the exercise, lick or Jam progression you have open), so you can ask "why is this bar hard?" or say "loop this bar slower" and tap the button it gives you. Spoken questions get short answers; typed questions get a fuller explanation (up to a few paragraphs) that stays until you close it. Answers from Gemini are read aloud in a natural Google voice you pick in Settings → You → AI helper (Gemini\'s voice); the built-in helper keeps the phone\'s own voice, so you can tell which one answered. If Google is busy it tries again, then a lighter Gemini model, then your other free key. It works without the internet; with a free AI key (Settings → You → AI helper) its answers get smarter and it can read pictures.', go: { settings: 'you' } },
      { title: 'Practice sessions', text: 'A session is a few timed steps, like "4 min warm-up, 10 min triads, 8 min triads over a beat". Each step opens the right screen, already set up. A bar at the top shows the step and the time left: ⏸ pauses, Next moves on, tap the bar for the step list, a tip, +2 min or Stop. Save sessions you like: they wait in Learn → Today → My practice sessions.', go: { learn: 'today' } },
      { title: 'Arrange your screens', text: 'Every screen is made of windows with a slim title bar: Tools (Tuner, Tempo, Chords, Scales), Songs, Learn, Jam, Settings and the Learn tools. Tap a window\'s name to fold it up. Drag ☰ to move a section up or down. Tap – to tuck it away: it waits as a button in the tray at the bottom, and one tap brings it back. Drag the ⇕ handle under a section to make it taller or shorter (⤢ puts it back to full size). "Reset layout" in the tray puts everything back the way it was.' },
      { title: 'The five sections', text: 'The bar at the bottom (or the side, on a big screen) has five sections. Play: play along with a tab. Songs: your songs, the songbook, the exercise library (about 800 exercises) and adding a new song. Learn: your daily plan, the course, lessons and progress. Jam: chord progressions with a band, soloing, making tabs and finding the chords of a song. Tools: tuner, metronome, chord library and scales. Most sections have a row of tabs across the top that splits them into a few short pages; each section remembers the page you were on, and tapping the section again in the menu takes you back to its start.' },
      { title: 'Search: just ask', text: 'Tap Search in the menu (or press / on a computer) and type what you want in your own words: "slow it down", "loop a hard part", "G7", "A minor pentatonic", "drop D", "metronome 90", "blues jam in A", "it doesn\'t hear me". Tap a result and it takes you straight there, already set up: the chord on screen, the tuner in that tuning, Play\'s Options open at the right setting (it flashes so you can see it). Typos are fine. If a song isn\'t in the app, it offers to look for its tab on Songsterr, Ultimate Guitar or Google.' },
      { title: 'The Back button', text: 'The phone\'s Back button closes whatever is open (a sheet, a picture, the menu), steps back a page (a lesson, a Settings page), and from any section takes you back to Play, or back to where a link or a search took you from. On Play with nothing open, press it twice to close KGuitar. On a computer the browser\'s Back button does the same.' },
      { title: 'Tune up first', text: 'Tools → Tuner. Play one string at a time; the needle and the note name show how far off you are. Turn the tuning peg until the note is green.', go: { tab: 'tuner' } },
      { title: 'Set up your input (2 minutes)', text: 'So the app hears you properly. It measures your room, how loud your strings are and how much delay your headphones add. Do it once for the phone mic (acoustic) and once for a USB amp or audio interface (electric). Until you do, the input button in Play (🎤 Auto) has a small yellow dot.', go: { settings: 'sound' }, tip: 'Settings is the gear icon at the top of Learn: Sound → Set up input. Or in Play: Options → Set up your input.' },
      { title: 'Tell it about you', text: 'The first time you open KGuitar it asks how long you\'ve played and what you want to get better at (songs, strumming chords, fingerpicking, lead and solos, timing, knowing the neck) and which styles you like (folk, bluegrass, reggae). Your daily plan, the songs it suggests and how much help the tab shows follow your answers. Change them any time in Learn → Settings → You → About you.', go: { settings: 'you' } },
      { title: 'Guitar or ukulele', text: 'Learn → Settings → You → Instrument. Pick guitar, tenor ukulele or baritone ukulele and the tuning. The whole app follows: chord shapes, tabs, tuner, quizzes. Songs are kept separately for each instrument, and the app asks "Are you sure?" before switching.', go: { settings: 'you' } },
    ],
  },
  {
    id: 'play', title: 'Play: playing along with tabs', intro: 'The heart of the app. Load a tab, tap Listen, and play. Each right note turns green and the cursor moves on.',
    items: [
      { title: 'Open a song', text: 'Tap Songs in the menu. It has four pages: My songs (everything you have added, with how far you got), Songbook (songs to learn), Exercises (the exercise library, plus the tab maker and the example songs) and Add a song. In Add a song you can search Songsterr and Ultimate Guitar right inside the phone app, upload Guitar Pro files (.gp, .gp5, .gpx), PDFs or text tabs (several at once, straight from Google Drive), or paste a tab or chord sheet you copied. Tap a song and it opens in Play.', go: { songs: 'add' } },
      { title: 'Songsterr and Ultimate Guitar, straight in (phone app)', text: 'Songs → Add a song: type the song, then tap Search Songsterr and Ultimate Guitar here. Songsterr results come in with every note and its rhythm (pick the guitar track if there are several); Ultimate Guitar brings the tab or chord sheet. Tap Open and it plays in KGuitar. Sharing a Songsterr or Ultimate Guitar page into KGuitar brings the tab in too. Pro and Official tabs on Ultimate Guitar can\'t be read; if a site changes how it works, the buttons below still open it in the browser.', go: { songs: 'add' }, phoneOnly: true },
      { title: 'PDF tabs', text: 'Upload (or share into KGuitar) a PDF: text tabs and chord sheets printed to PDF are read line by line, and Guitar Pro or Songsterr prints are read from their staff lines, so every number lands on its string with the bar lines kept. A scanned PDF (just pictures of pages) goes to the picture reader, which reads the tab with the AI.', go: { songs: 'add' } },
      { title: 'Songbook: songs to learn', text: 'Songs → Songbook has folk, bluegrass, reggae and classical songs and KGuitar originals, from beginner to advanced. The old songs and fiddle tunes are public domain; Classical has Romanza, Greensleeves, Für Elise, Minuet in G and Canon in D. The KGuitar originals are whole instrumentals in your styles: prog (Plini/Syncatto, Polyphia, Petrucci and Lee McKinney, Vai and Roy Ziv), blues and classic rock, pop, funk, modern country, acoustic, reggae rock and dub, Hawaiian slack key in open G, and fingerstyle (Marco Cirillo, Sungha Jung). Each song has parts to learn in order (Words & chords, the Melody, rhythm parts, The whole piece …). Filter by style and level; drums and bass play along with Hear it and In time.', go: { songs: 'songbook' } },
      { title: 'Song check', text: 'Tap the song\'s name at the top of Play. It shows how hard the song is for you, the chords (and which need a barre), the techniques in it (bends, slides, hammer-ons …), the hardest bar (with a button to loop it), how far up the neck it goes, and a speed to start at. It opens by itself the first time you open a new song. If the song is in another tuning or needs a capo, a note says so, with a button that sets the tuner to that tuning.' },
      { title: 'Share straight into KGuitar', text: 'In a browser or tab site, select the tab text (or a whole chord sheet), tap Share, then KGuitar. Guitar Pro files from Drive or Downloads can be shared to KGuitar the same way ("Send a copy" in Drive). Sharing a YouTube link adds that video to the song you have open.' },
      { title: 'Listen: wait for me', text: 'Tap Listen and play. The app waits for each note, so go as slowly as you like. A wrong note shows what you played and what the tab wants. If you know you played it right and the app misheard you, tap "I played it right" (or a pedal set to it): it moves on, and from then on it counts that same sound as the right note on that input (phone mic and USB amp learn separately; Options → Learned shows how many and can forget them). The box at the top shows the next note and where it is. Under it, one row of controls: Wait for me / In time, Loop, Hear it, and Options (the sliders button) for everything else.', go: { tab: 'play' } },
      { title: 'Chord sheets: strum along', text: 'Songs with chords written over the words (the most common way songs are shared) open as a strum-along: one chord per bar with its shape and the words underneath. Strum the chord and let it ring; the app checks all the notes of the chord. Try "Amazing Grace" in Songs → Exercises → Example songs.', go: { songs: 'practice' } },
      { title: 'In time: keep the beat', text: 'Switch "Wait for me" to "In time" and tap Start. A big 5-4-3-2-1 gives you time to get your hands on the guitar (change it in Settings → You → Get ready time), then a count-in bar shows a huge 4 3 2 1 over the tab, and the tab scrolls at tempo with a click; every note is marked on time, early or late, and you get a score at the end. Hear tab too plays the tab quietly along with you. When you play a song or loop cleanly in Wait for me, a note suggests the next step: Try In time, at ¾ speed.' },
      { title: 'Play with the band', text: 'Options → Play with the band adds the rest of the band to Hear it and In time: a Guitar Pro file\'s drums, bass and other guitars, or drums and bass made from the chords for songbook songs. Turn it off to hear just your part.' },
      { title: 'Count it: 1 & 2 &', text: 'Options → Count it: 1 & 2 & shows the rhythm under the tab: note stems, beams and the count for every note, so you can count out loud while you play. On a chord sheet, Options → Strum puts a strum pattern over each chord instead (arrows: down, up, B for a bass note and × for a chop, a quick muted strum), and In time checks each strum. Pick a pattern that suits the song, from plain downstrokes to reggae chops and waltz.' },
      { title: 'Chord help', text: 'When a strummed chord isn\'t right, the box under the next note says what\'s wrong: which note of the chord isn\'t ringing and which string to check, or which extra note rang out that doesn\'t belong.' },
      { title: 'Record yourself', text: 'Options → ⏺ Record yourself records what the mic or amp hears while you play. A red timer button appears next to Hear it: tap it to stop, then listen back in the bar under the tab. Save keeps it as a file (share it to Drive or a friend); ✕ throws it away. Nothing is recorded unless you tap Record, apart from Then vs now (below), which you can switch off in Options.' },
      { title: 'Report card', text: 'After a whole run-through (Wait for me or In time) a card shows your score in a ring, how it compares with last time, and the bars that went wrong, marked with a dashed red box on the tab. One button does the most useful next thing: loop those bars (at 70% in In time), try it In time once Wait for me is clean, or speed up. ✕ closes it; starting again clears it.', go: { tab: 'play' } },
      { title: 'Then vs now', text: 'Play quietly keeps two recordings of each song, on this phone only: your first whole run of it, and later your best run once it is at least 10 points better. When that happens the report card shows a Then vs now button: your first try and your best, side by side with their scores and dates. Tapping one stops the other, so you can flip between them. They are also in Learn → Explore → My recordings. Switch it off in Play → Options → Then vs now.', go: { tool: 'recordings' } },
      { title: 'Talk to the helper (hands-free)', text: 'Tap the microphone button beside the helper bubble and just say it: "slower", "loop bars 5 to 8 and slow the tempo", "full speed", "stop looping", "explain this hand position", "what does an augmented chord do?". Loop and speed changes happen straight away; the answer shows in a small card beside the bubble and is read out, so the tab stays in view. Tick Keep talking and it listens again after each answer, for a back-and-forth while you play (it stops after a few quiet tries). While you talk, Play doesn\'t count your voice as wrong notes. Uses the phone\'s speech recognition (needs the internet on most phones). With the USB amp plugged in, the phone may listen to the amp instead of you: unplug it, or use Chat. The spoken answer stays on screen for 30 seconds; Settings → You → AI helper changes that (12 s, 30 s, 1 min or until you close it).' },
      { title: 'Music stand', text: 'Tap Stand (the note button) at the top of Play for a view you can read from across the room: just the tab, much bigger, and one slim row of buttons at the very bottom: Listen / Start, Loop bar (loops the bar you\'re on; tap again to stop), − speed % +, back to the start, Big, and ✕ to leave (or the phone\'s Back). In the phone app the phone\'s own bar at the bottom (home, back, recent apps) hides while the stand is open: swipe up from the bottom edge to bring it back for a moment. Pinch the tab to set its music-stand size; it remembers it separately from the normal size.' },
      { title: 'Big view (the Fold closed)', text: 'On a narrow screen, like the Fold\'s cover screen, Stand opens the big view: the next note (fret and string) or chord, huge, the bar number, and the chord coming next. The box turns green when you get it and red when you don\'t, so you can see it from a few feet away. Underneath are big Listen, Loop, − speed +, and back-to-the-start buttons. Show the tab switches to the big tab; on the inner screen tap Big in the stand bar to get this view.', go: { tab: 'play' } },
      { title: 'Tidy up while I play', text: 'On by default (Play → Options). When you tap Listen or Start, the Scales & chords panel, the side panel and the menu fold away so the tab gets the room, with a small readout above it. A video that\'s showing stays. When you stop, everything comes back. Switch it off in Options if you\'d rather keep your layout.' },
      { title: 'Peek at a chord shape', text: 'In Play, press and hold any chord name (above the tab, or in the Scales & chords strip). A big chord box pops up next to your finger: the shape the tab uses, or a common shape. It stays while you hold and goes away 1.5 seconds after you let go. Nothing stops: your loop, the tab and the listening keep going.' },
      { title: 'Loop a section + speed trainer', text: 'Tap ⟲ Loop, then the first and last bar of the hard part. The loop bars are shaded with bold lines at the start and end. It repeats and scores each pass, and "⟲ Again" flashes on the tab each time it goes round with your last score; the ✕ on the loop button stops looping. In In time mode, Options → Speed trainer starts slow and speeds up a little every time you score 90% or better.' },
      { title: 'Hear it', text: 'Plays the tab so you know how it should sound, with the cursor moving along. Options → Speed (½, ¾) slows it down, and Options → Sound switches between acoustic, J-45, nylon, clean electric, crunch and distorted. On Auto, a Guitar Pro file plays in its own guitar sound, and palm mutes (PM) and power chords play as real recorded palm mutes and power chords on the amp sounds.' },
      { title: 'Frets, notes or both', text: 'Options → Numbers: Frets shows the tab numbers, Notes shows the note names, Both shows each number with its note. Tap any number in the tab to hear it and start from there. Options → Size (A− / A+) changes the size of the tab, or pinch it with two fingers.' },
      { title: 'Rests', text: 'Long stretches with nothing to play (a part that comes in late, a long break) are squeezed into one short block that says how many bars to rest, so the tab starts where your part starts. Tap the block to start from there.' },
      { title: 'YouTube video beside the tab', text: 'Tap Video and paste a YouTube link. The video sits in a small folding panel: speed buttons slow it down, and A and B set a loop. Sync with tab lines the video up with the tab so, in In time mode, the tab scrolls with the recording. If a video says it can\'t play here, its owner blocks other apps: use Open in YouTube.' },
      { title: 'Sync by tapping', text: 'In Sync with tab, play the video and tap Tap along on every beat, starting on the first beat of the tab. After 8 taps the tempo and start point are set; keep tapping to make it more exact. Set it by hand is still there if you prefer.' },
      { title: 'Scales & chords for soloing', text: 'The panel under the tab (or Scales & chords on small screens) shows the song\'s key, the scales that fit, the chords, and the fretboard. Arpeggio shows the chord\'s notes, Triads small chord shapes, Connect how to move smoothly to the next chord.' },
      { title: 'Split screen on a folding phone', text: 'Half-fold a Galaxy Fold like a little laptop and Play puts the video and readout on top and the tab on the bottom. Options → Split screen does the same on any phone or tablet.' },
      { title: 'Make the tab bigger', text: 'Drag the bars between the panels (the little grey handles) to give the tab more room, or drag a panel all the way to tuck it away; tap its arrow to bring it back. Drag ☰ Move on a bar to put that panel somewhere else: on the phone above or below the tab, on the big screen left or right (video and readout) and above or below (Scales & chords). Options → Move the panels → Put them back undoes it. The ⤢ button at the top (Full tab) hides everything but the tab and a slim note readout. Play remembers how you left it.' },
      { title: 'Where your fingers go', text: 'A small floating window shows where your fretting hand sits: the four frets it covers are shaded ("Index on fret 5"), and every note has the finger that plays it, in colour: 1 index blue, 2 middle green, 3 ring orange, 4 pinky red, open strings white. The note to play next is ringed. Two beats before your hand has to move, a gold "Upcoming shift" badge shows where to, with a dashed outline of the next position, the reason ("in the rest", "while the open B rings", "slide up with finger 3") and Loop this shift, which loops just those two bars. Drag the window by its top bar anywhere, make it bigger from its corner, tuck it into a chip with –. When it sits over the note you are on it fades so you can still tap the tab. Options → Where your fingers go turns it off and on.' },
      { title: 'Fingering engine', text: 'Every tab in KGuitar is fingered by one engine that plans your hand like a teacher: it looks ahead over the whole phrase, uses one finger per fret, measures stretches in real distance for your hand size (frets are wider near the nut), barres when one finger holds a fret, bends with the ring finger, keeps hammer-ons in one position, slides with the same finger, and moves your hand in rests, on long notes and while open strings ring. Tabs you load keep their frets: only the fingers are worked out. Settings → You → Your hand sets small, medium or large.' },
      { title: 'The 5-layer neck', text: 'Everything a chord shape holds, stacked under one hand. Pick a shape (C, A, G, E or D), then switch the layers on and off: Shape (the chord), Triads (three-note triads hiding inside it), Pentatonic (the five-note box around it), Mode notes (the two notes that turn the box into a full mode: pick Major, Lydian or Mixolydian, or Minor, Dorian or Phrygian) and Free fingers (violet rings: sus2, sus4, add9, 6th and 7th notes a spare finger can reach while you hold the chord; tap one to hear the chord and then that hammer-on). 3 per string shows the whole mode three notes per string from the shape\'s root. Drone holds a soft chord under you while you try things. The buttons under it jump to the same chord in Chords or the CAGED explorer, or the mode in Scales. It is in the CAGED explorer (pick one shape), Play → Scales & chords → Layers (the chord you are on, in the shape nearest your hand), Tools → Chords and Tools → Scales, and in the chord peek: hold a chord name, then Pin open.' },
      { title: 'Voice leading', text: 'Chord shapes chosen so your hand barely moves from one chord to the next. Gold rings are notes both chords share: keep that finger down. Gold arrows are the 3rds and 7ths (the notes that make a change sound like a change) sliding a fret or two; dashed arrows are other fingers. The line under the neck says it in words ("Hold G; B up a half step to C"). Pick where on the neck (low, middle, high) and 3 or 4 strings. Practise the changes opens the progression in Play as a tab, two bars per chord, four times round, and Wait for me listens for each chord. It is in Tools → Chords (from the chord you picked to its usual next chords), the CAGED explorer (common progressions in your key), Jam → Solo over it (your Jam progression, following the loop while it plays) and Play → Scales & chords → Connect → Voice leading shapes.' },
      { title: 'Play the changes', text: 'Soloing that follows the chords: the neck shows the chord you are on in gold (root, 3rd, 5th, 7th and the 9th), the rest of the scale faintly, and two beats before the chord changes, the next chord\'s 3rd and root light up cyan with an arrow from the nearest gold note, so your line lands on the change. Jam → Solo over it → Neck (Play the changes) and Play → Scales & chords → Scale (Play the changes); it follows Hear it, In time and the Jam loop.' },
      { title: 'Play it in your tuning, or without the capo', text: 'When a tab is in another tuning (Drop D, open G…), the notice above the tab offers Tune to it or Play it in your tuning: the same notes, moved to fit, with a line saying what changed ("6th string D→E: notes 2 frets lower"; notes lower than your lowest string go up an octave). As written puts it back. A tab with a capo can be played without it: Options → Capo → Without capo. Chord sheets get Smart capo in Options: the capo fret that turns barre chords into open shapes (a song in Eb with capo 1 is D G A Bm); it sounds the same.' },
      { title: 'Make it easier, and your own fingering', text: 'Play → Options → Fingering → Easier for my hand plays the same notes on the strings and frets that are easiest for your hand and level (low on the neck, open strings welcome, few shifts). As written puts the tab back. Tap any note to see which finger plays it: tap 1, 2, 3 or 4 to choose your own, or Other string to play the same note somewhere else; the engine plans the rest around your choice, and it is saved with the song.' },
    ],
  },
  {
    id: 'exercises', title: 'Exercises: the practice library', intro: 'About 800 short exercises, like a teacher\'s workbook: every technique and a lot of theory, from your first warm-up to sweep picking. Songs → Exercises.',
    items: [
      { title: 'Where your left hand goes', text: 'Under every exercise, lick and generated tab there is a row of small necks, one for each hand position: "1st finger on fret 5", with the finger for every note (1 index, 2 middle, 3 ring, 4 pinky). Keep your hand there until the next card, then slide the whole hand. The one being played lights up. Hide it with "Hide hand".', go: { songs: 'practice' } },
      { title: 'Find an exercise', text: 'Three menus at the top filter the list: Difficulty (Beginner to Expert), Type (warm-ups, picking, legato, bends, scales, arpeggios, chord changes, strumming, fingerstyle, every style of lick …) and Technique (alternate picking, hammer-ons, sweeps, palm muting …). Type → Start here shows the essentials to learn first. "Exercise 12 of 787" says where you are; ‹ and › step through, the long menu jumps anywhere, 🎲 Random picks one, ↺ Clear resets the filters. Tap ☆ to keep an exercise in your favourites and tick Favourites only to see just those.', go: { songs: 'practice' } },
      { title: 'Hear it, then play it', text: 'Pick a Key (exercises that move use any key they fit; open-string ones use a capo), a Guitar sound and a Tempo. ▶ Play plays it with a one-bar Count-in, a Metronome click and, if you like, a Loop. The card shows the chord, the neck with every note numbered in the order you play it (roots in red; chords show their shape), and the tab with the counts under it. Tap any note in the tab to hear it and start from there, or drag the slider.', go: { songs: 'practice' } },
      { title: 'Play along: it listens', text: 'Play along (it listens) opens the exercise in Play at your tempo: Wait for me checks every note, In time scores your timing, and the speed trainer can take it faster each time. Licks with a breakdown also have a "How to play it, step by step" button.', go: { songs: 'practice' } },
      { title: 'Melodic fingerstyle', text: 'Type → Melodic fingerstyle: the beautiful, peaceful acoustic sound. Open-string chords (Cadd9, Em7, D/F#, add9s and maj7s) picked p-i-m-a, hammer-ons that make a sus chord bloom into a major one, harmonic bells, cascading scales where every note rings into the next like a harp, a Spanish melody, a chord melody, and progressions like the Canon. Learn → Technique has a lesson on it, the lick library has its phrases explained, and Jam has it as a style.', go: { songs: 'practice' } },
      { title: 'Chord tones through the changes', text: 'Type → Chord tones through the changes teaches you to solo with the chords, not just the scale: arpeggios on every chord, moving to the nearest note of each new chord, guide tones (the 3rds and 7ths) and landing on the 3rd right as the chord changes, over a ii–V–I, a 12-bar blues and more.', go: { songs: 'practice' } },
    ],
  },
  {
    id: 'learn', title: 'Learn: your daily practice', intro: 'Open Learn every day. It shows what to practise, keeps your streak and tracks everything.',
    items: [
      { title: 'Zero to Hero (guitar)', text: 'Learn → Course follows your Zero to Hero plan: five phases, each ending in a gate (a short skill check) before the next. Tick what you can already do and it starts you at the right week. "Today\'s routine" runs the five daily blocks (warm-up, chords and rhythm, your current skill, fretboard and ear, songs) as a session in 20, 45 or 60 minutes; Saturday is song day. Gate items the app can measure tick themselves; tap "I can do it" for the rest. Each phase links to the free JustinGuitar lessons that go with it.', go: { learn: 'course' } },
      { title: 'Style paths', text: 'Learn → Course → Zero to Hero → Style paths: go deep on one style next to the main plan (bluegrass flatpicking, acoustic songwriting, reggae rock, blues-rock, pop and soul, melodic prog and metal, Hawaiian slack key, classical guitar, fingerstyle). Tap Follow and that path\'s next step joins today\'s routine. Each step opens the right licks, exercises, songbook songs or Jam style; tap ✓ when you\'ve got it. Everything in a path is also open on its own any time.', go: { learn: 'course' } },
      { title: 'Lesson videos in Zero to Hero', text: 'Most steps in Zero to Hero and the style paths have a ▶ Watch button: a YouTube lesson for exactly that skill, from the best teacher for it (the style paths use players of that style: Tyler Grant and Molly Tuttle for flatpicking, Cory Wong for funk, Marco Cirillo for fingerstyle, Jeff Peterson for slack key …). It plays right there and is ticked ✓ Watched once you play it. Every other day, Today\'s routine adds one video you haven\'t watched yet.', go: { learn: 'course' } },
      { title: 'Hawaiian slack key', text: 'Learn → Explore → Technique has four slack key lessons: open G (taro patch: D G D G B D), the alternating thumb with the melody on top, hammer-ons, pull-offs and sweet 6ths, and harmonics with the Hawaiian vamp. Each has a video from a slack key teacher and a drill that listens to you (the open G thumb drill, Kona Morning, Trade Wind Vamp). The Tuner has Open G and C wahine; Jam has a Hawaiian slack key style, Make a tab writes slack key phrases in open G, and the Songbook has Hawaiian & slack key pieces.', go: { tool: 'techniques' } },
      { title: 'Practice: one button', text: 'At the top of Learn → Today and Songs → My songs. Tap Practice and the app plans it for you, and shows the plan underneath: a warm-up at your level, what your Zero to Hero plan is on now, the bars that go wrong most in a song you\'ve played lately (looped at 70% speed), then a song: one that\'s due for a review, the one you were on, or one from the songbook. Pick 10, 20 or 30 minutes. It runs as a session: the bar at the top counts each step down and moves you on. Just carry on goes straight back to your last song, same bar, loop and speed.', go: { learn: 'today' } },
      { title: 'Lick chainer', text: 'Learn → Explore → Lick chainer (also in Songs → Exercises, and "＋ Add to my lick chain" on every must-know lick). Tap licks to line them up like train cars, drag ⠿ or use ‹ › to reorder, ×2 to repeat one. They all move to one key and each sits near where the last ended on the neck. "Add one that flows" picks a lick that starts close to where your chain ends. Pick the key, tempo and the space between licks, hear it, then Play along and it listens.', go: { tool: 'chainer' } },
      { title: 'Suggested exercises', text: 'Songs → Exercises opens with three picks for today: a warm-up, what your plan is working on, and one at your level or a step further. Tap one to load it in "Play it". All the others are still below.', go: { songs: 'practice' } },
      { title: 'My recordings', text: 'After you record yourself in Play (Options → Record yourself), tap "Keep it" and the take goes into Learn → Explore → My recordings, grouped by month. "Then vs now" at the top shows the first try and best run Play kept for each song, and pairs your own takes of the same song too, so you can hear how far you\'ve come. Add a note to any take, save a copy to the phone, or delete one (it asks first).', go: { tool: 'recordings' } },
      { title: 'Today, Course and Explore', text: 'Learn has three pages. Today: the today card, your plan for today and the daily quests. Course: the practice course quizzes and the path to mastery. Explore: every Learn tool in three groups (Play better, Ears and theory, You). The number on Today is how many plan steps are left.', go: { learn: 'today' } },
      { title: 'Today card', text: 'The pick fills up as you practise toward your daily goal and turns into a green check when you reach it. Any 5 minutes keeps your streak alive. Every 7 days in a row earns a streak freeze that saves a missed day.' },
      { title: "I'm away from my guitar", text: 'Tap it when you don\'t have your instrument (work, travel). The plan and quests switch to things you can do without it (lessons, tap quizzes, ear training with headphones) and it still counts. It switches itself off after 30 hours.' },
      { title: "Today's plan", text: 'A short session made for you: tune up, warm up, a quiz, a song (or the bars you keep missing, or a song due for review), and one more skill. It follows your level and goals (About you): a beginner gets chord changes and an easy songbook part, someone who likes bluegrass gets bluegrass songs. Tap a step to go straight there; it ticks itself off.' },
      { title: 'Daily quests and levels', text: 'Three small challenges a day for extra XP. XP comes from practice time and right answers; levels and badges come with it.' },
      { title: 'Practice course', text: 'Learn → Course: tap Continue for your next quiz, or open a topic to pick one. Quizzes on fretboard notes, chords, triads, the circle of fifths and CAGED. Answer by tapping, or switch to Play and answer on your instrument (the mic checks it). What you miss comes back more often until it sticks. Up to three stars per quiz.', go: { learn: 'course' } },
      { title: 'Path to mastery', text: 'Learn → Course, under the quizzes: seven stages from first steps to mastery, each with goals that tick off on their own as you hit them. Tap a goal to work on it.', go: { learn: 'course' } },
      { title: 'Ear training', text: 'A soft drone plays the home note of a key; then a note plays and you name it by how it feels against home. After each answer it walks back home. Levels unlock as you go. Turn on "Use my guitar" to answer by playing the note.', go: { tool: 'ear' } },
      { title: 'Theory lessons: read, watch, play', text: 'Short lessons from the basics to harmony, plus CAGED and how to practise. Each has three steps: 1 Read (with sounds to tap), 2 Watch (a YouTube video that explains the same idea on the guitar; it plays right in the lesson, or Open in YouTube), 3 Play (exercises with tabs that open in Play and listen to you). On ukulele, lessons switch to a ukulele teacher where there is a good one (and a baritone teacher on baritone; otherwise the guitar video, since a baritone is tuned like the guitar\'s top four strings). Each lesson links to the full chapter on Offtonic Theory.', go: { tool: 'lessons' } },
      { title: 'Technique', text: 'Learn → Explore → Technique: holding the pick, clean fretting, first chords, strumming, alternate picking, muting, palm muting, hammer-ons and pull-offs, slides, bends, barre chords and Travis picking. Each has what to aim for, a lesson video, and a drill tab that listens to you. Skills you have practised are ticked.', go: { tool: 'techniques' } },
      { title: 'Must-know licks', text: 'Learn → Explore → Must-know licks: the licks every player of a style should know, in 16 styles, each with a breakdown: what it is, how to play it step by step, the secret to making it sound right, where to use it and a tempo to aim for. Pick a key (open-string styles use a capo), hear it at full or slow speed, then Play along and the app listens.', go: { licks: 'blues' } },
      { title: 'Your video lessons (phone app)', text: 'Learn → Explore → Your video lessons plays course videos you have on the phone. Copy the course folder onto the phone (USB cable, or download it from Google Drive), tap Find my lessons and choose the folder. The lessons show chapter by chapter with a Continue button; each video has speeds from ¼× to 1¼×, ±5 seconds, an A–B loop, Mirror (flips the picture so the teacher\'s hands match yours), resume and a Done tick. A chapter\'s Guitar Pro or text tabs open in Play with the video beside them (sync it with the tab like a YouTube video); PDFs open in your PDF app. Nothing is copied or uploaded, and it isn\'t in the web version.', go: { tool: 'videos' }, phoneOnly: true },
      { title: 'Bends & vibrato', text: 'Pick a string, a fret and how far to bend (½ step, whole step or 1½ steps), bend and watch the needle: it turns green when the bend reaches the right pitch and holds there. Vibrato mode shows how wide and how fast your wobble is, and a trace draws your pitch over time.', go: { tool: 'bends' } },
      { title: 'CAGED explorer', text: 'Any chord in five shapes up the whole neck, with the arpeggio, pentatonic, scale and triads inside each shape.', go: { tool: 'caged' } },
      { title: 'Circle of fifths', text: 'Tap a key to see its chords and key signature and hear how they sound. Every key on the circle shows how many sharps or flats it has (2♯, 3♭ …), so you can read key signatures at a glance. The same circle is in Jam → Solo over it.', go: { tool: 'circle' } },
      { title: 'One-minute chord changes', text: 'Switch between two chords as many times as you can in a minute. Tap for each clean change, or let it listen and count for you. Do it daily and watch the number climb.', go: { tool: 'changes' } },
      { title: 'Rhythm trainer', text: 'Listen to a bar, then a bar of clicks counts you in (1, 2, 3, 4), then tap it back (or strum it) against the click. Nine levels from quarter notes to swing. Each tap gives a little buzz (Buzz) and, if you like, a tiny tap sound (Tap sound).', go: { tool: 'rhythm' } },
      { title: 'Progress', text: 'Your practice calendar, this week compared with last, badges and how well you know each part of the course. Skill trends show small graphs of your chord changes a minute, how on time you are in In time, your rhythm trainer scores and the speed you play each song cleanly, so you can see yourself getting better.', go: { tool: 'progress' } },
    ],
  },
  {
    id: 'jam', title: 'Jam: progressions and looping', intro: 'Make chord progressions to play over, with strumming and drums, and record yourself as a loop.',
    items: [
      { title: 'Beat maker', text: 'Jam → Beat maker. Drum on the pads with several fingers at once: kick, snare and hi-hat are the three big ones, and hitting nearer the top of a pad is louder. Pick a style under "Start from", or build it yourself. Pads Small/Medium/Big changes their size.', go: { jam: 'beats' } },
      { title: 'Sample mode: record onto a pad', text: 'Beat maker → Pads → Sample (or Your pads): hold a pad and make a sound (your voice, a guitar hit, a knock on the body); let go and it\'s on the pad, trimmed. A quick tap opens the pad\'s settings: pitch, volume, play backwards, one shot / only while held / loops while held, fades, and a choke group (a pad that cuts off the others, like a hi-hat). Pads can also play an instrument note or a whole chord, or a file from your phone. Your pads has 16 of your own.', go: { jam: 'beats' } },
      { title: 'Chop a riff onto pads, and Keys mode', text: 'Chop records a riff and cuts it at every note you pick: the notes land on Your pads, one per pad, to play in any order. In the Keyboard, Sound → Your pads plays one recorded pad up and down the keys (it finds the note you recorded).', go: { jam: 'beats' } },
      { title: 'Effects pad', text: 'Effects: pick Filter, Echo, Reverb, Stutter, Crush or Gate and drag a finger round the square to play with the whole beat (the labels say what left–right and up–down do). Let go and it goes back to normal.', go: { jam: 'beats' } },
      { title: 'Parts A–D and song mode', text: 'The beat has four parts (A, B, C, D): make a new one empty or as a copy, and the pads, steps and loops play the part you\'re on. Song chains the parts in the order you set (A A B A …) so the beat plays as a whole song.', go: { jam: 'beats' } },
      { title: 'Bounce and save', text: 'Bounce turns the whole beat into one loop (or onto a pad) so you can build on it; Undo brings the parts back. Save as WAV makes a sound file of the beat (and, if you like, one file per part: drums, keys, loops) to share.', go: { jam: 'beats' } },
      { title: 'Undo and redo', text: '↶ and ↷ in the beat maker step back and forward through your changes (Ctrl+Z / Ctrl+Shift+Z on a keyboard).', go: { jam: 'beats' } },
      { title: 'Build a beat loop by loop', text: 'In Drum layers, tap a pattern ("Hi-hat 8ths", "Off-beat hi-hat", "Four-on-the-floor kick", "Snare on 2 and 4"…) to add it as a layer: no tapping a hi-hat 64 times. Or press ● and play the pads: each time round the loop becomes its own layer, snapped to the beat, so your timing doesn\'t have to be perfect. Mute (M), remove (✕) or undo the last layer any time.', go: { jam: 'beats' } },
      { title: 'Keys and chords', text: 'The Keyboard plays pianos, organs, strings, choirs, synths and more. "Chords" plays a whole chord from one key (pick major, minor, 7, 9, dim and more, or hold a type with one hand while playing with the other); "Chords in (key)" plays the right chord for the song\'s key. Every note of the chord lights up, and the neck below shows the same chord on guitar. Press ● and what you play goes into the piano roll.', go: { jam: 'beats' } },
      { title: 'Loops that line up with the beat', text: 'Looper (in the beat maker): "On the beat" counts you in, records exactly from bar 1 and stops itself. "Free" lets you start and stop whenever and stretches the take to whole bars. Auto-align nudges what you played onto the beat. A foot pedal works too: right = record the next loop, left = undo it, hold right = stop.', go: { jam: 'beats' } },
      { title: 'Practise over your beat', text: 'Tap "Practise over it" in the tray: the neck shows a scale in the beat\'s key, and the notes of the chord playing now light up gold. Pick a lick to try over it; its hand positions show underneath.', go: { jam: 'beats' } },
      { title: 'Tab from a screenshot', text: 'When a video shows the tab on screen: pause it, take a screenshot (or a few, in order), and add them in Jam → Find chords or Songs → Add a song. The AI reads them into a tab you can play along with, with the video beside it. It needs the free Google Gemini key. Listening with the mic is good for chords; for single notes it only works well when one instrument is playing.', go: { jam: 'find' } },
      { title: 'Make a progression', text: 'Jam has four pages: Jam, Solo over it, Make a tab and Find chords. On Jam, tap New progression. Every chord shows its shape; lock the ones you like (the padlock) and tap New progression again to change the rest. Options (top right) sets the key, style, how many chords, chord colours, endings and how adventurous it gets. Famous progressions are at the bottom.', go: { jam: 'jam' } },
      { title: 'Play along', text: 'Tap Play loop for guitar, bass, drums and a click. The drums play a fill at the end of each pass and a crash when it comes round again. Solo over it shows the scales that fit, the fretboard and the circle of fifths, with a small Play loop button at the top so you can start and stop the band from there.' },
      { title: 'Guitar sound, bass and drums', text: 'Each style picks its own sound: metal gets the distorted amp with palm mutes and power chords, rock and blues get crunch, funk, reggae and country get clean electric, folk and slack key get the J-45 acoustic, jazz a warm jazz guitar, classical nylon. Tap the Band line under Play loop to change the guitar sound, strum, drums or bass any time. On the amp sounds the backing guitar is double-tracked (two takes, left and right), like a real rhythm part. The drums are a real recorded kit (double kick for metal, one drop, rockers and steppers for reggae with the cross-stick), and the bass follows the chords: walking for jazz, root–fifth for country, eighths for rock.' },
      { title: 'Looper', text: 'Jam page → Looper (below the chords). Record a loop: it waits for the start of the next pass and records exactly one loop in time with the drums. Add more layers on top. Each layer can play backwards, at half speed, or through an effect (echo, far away, space). If loops sound a little late, run Timing check once, or nudge a layer Earlier/Later.', go: { jam: 'jam' } },
      { title: 'Make a tab', text: 'Jam → Make a tab has four parts: Fingerpicking (your chords as Travis picking, arpeggios, slack key, a melodic fingerstyle roll, percussive slaps, classical triplets and more), Licks & solos, Chord melody and Riffs. Pick a style (it follows Jam\'s style until you choose another), a length and a level. Every tap writes a new one over your chords: an idea, its answer and an ending that lands home, with the style\'s own techniques (bends, slides, legato, taps, harmonics, double stops, ghost notes). Preview plays it; Open in Play follows you note by note. The same maker is in Songs → Exercises, over a style\'s own chords in any key.', go: { jam: 'tab' } },
      { title: 'Chord melody', text: 'Writes a singable tune over your chords with the chords under it, arranged the way the style does it: slack key and Travis keep the thumb going, classical ripples the inner notes, melodic fingerstyle lets open strings ring, country goes boom-chick, jazz and neo-soul put 3rds and 7ths under the tune, Hawaiian doubles it in 6ths. Melody only and Melody + bass are easier versions; tap again for a new one.' },
      { title: 'Licks, solos and riffs: the styles', text: '21 styles, each built from how the players you like really play (each style lists players to listen to): melodic prog, prog-pop (tapping and hybrid picking), shred and melodic rock, prog metal, heavy metal, blues-pop, classic rock, blues, pop and soul, neo-soul, funk, jazz, modern country, bluegrass, modern flatpicking, acoustic singer-songwriter, reggae rock, Hawaiian slack key in open G, Hawaiian, melodic fingerstyle and classical. Only bluegrass stays near the headstock (with a capo, like the pickers); the others use the neck the way those players do. Riffs: djent and gallops, power chords, funk 16ths, reggae skanks and dub lines.' },
      { title: 'Find the chords from a song', text: 'Jam → Find chords. Play a song out loud near the phone (a YouTube video on the speaker, a record) and tap Listen: KGuitar listens through the mic and writes down the chords and the key (a guess you can check). Chords mode is for strummed songs; Notes is a quick rough guess at a single-note line. It tells playing from talking and singing: talking is always left out, and singing is left out unless you turn on Include singing. Tap a chord to change it, then Use in Jam to jam over it, or open it in Play. Pulling every note out of a full band mix isn\'t reliable yet (for anyone): for exact notes use Notes from a recording below, or bring the real tab in from Songsterr.', go: { jam: 'find' } },
      { title: 'Notes from a recording (accurate)', text: 'Jam → Find chords → Notes from a recording: Record yourself playing (or a solo guitar lesson on the speaker), or pick an audio or video file. A note detector made for this (Basic Pitch, by Spotify) writes down every note right on the phone, even chords. Choose Single notes or With chords, fix the tempo if the rhythm looks off, and Open as a tab. Works best with one instrument at a time.', go: { jam: 'find' } },
      { title: 'Backing guitar', text: 'Turn off Backing guitar to keep just the bass and drums while you play the chords yourself (on the Hear row: Backing guitar, Bass, Drums, Click). The app never plays your own guitar back: what you play through the amp stays in your amp.' },
    ],
  },
  {
    id: 'tools', title: 'Tools', intro: 'Everyday helpers.',
    items: [
      { title: 'Tuner', text: 'Open it and it starts listening straight away: no Start button. Pluck one string and let it ring. The big needle and the cents number (to a tenth of a cent) show how far off you are, the frequency is underneath, and the advice says which way to turn. The string it hears lights up; tap a string to tune just that one, or leave it on Auto. The reading holds steady while the note rings, so you can turn the peg slowly. Standard and alternate tunings, plus reference tones to tune by ear.', go: { tab: 'tuner' } },
      { title: 'Tempo (metronome)', text: 'Accents, subdivisions, odd time signatures, tap tempo and a speed trainer. Sounds include a real cross-stick, cowbell and hi-hat, and Drum beat swaps the click for a recorded drummer (rock, metal, reggae, swing …) at any tempo, with a fill every 8 bars.' },
      { title: 'Chords', text: 'Every common chord in every key, with several shapes. Tap a shape to hear it. Under the shapes: ▶ The chord, ▶ As an arpeggio and ▶ Its scale let you hear it three ways, Scales that fit lists the scales to solo with (▶ to hear, On the neck to see them), and Licks that sound good over it gives licks in many styles placed on this chord, to hear, learn or play along with.' },
      { title: 'Scales', text: '22 scales and modes on the whole neck or one position at a time.' },
    ],
  },
  {
    id: 'gear', title: 'Your gear', intro: 'KGuitar works with the phone mic for acoustic instruments and with a USB amp or audio interface for electric.',
    items: [
      { title: 'Acoustic: the phone mic', text: 'Hold or prop the phone 30–50 cm from the soundhole. Quiet rooms work best. Use headphones for videos and backing so the mic hears only you.' },
      { title: 'Electric: USB amp or interface', text: 'Plug a USB multi-effects pedal, headphone amp or audio interface (for example the Sonicake Pocket Master) into the phone\'s or tablet\'s USB-C port. Automatic input picks it up when it\'s plugged in. Use a clean or lightly driven sound while learning; heavy effects make notes harder to tell apart.' },
      { title: 'Hands-free with a footswitch', text: 'Pair a Bluetooth page-turner or footswitch: right pedal starts and stops, left pedal goes back to the start. Settings → Sound → Hands-free lets you set what each pedal does (loop this bar, next bar, Hear it, video …). USB MIDI pedals work too.', go: { settings: 'sound' } },
      { title: 'Sound', text: 'Hear it, tapped notes and the quizzes use real guitar sounds. Pick one in Play → Options → Sound or in Settings → Sound → Playback sound: Acoustic, Acoustic J-45, Nylon (great for ukulele), Clean electric, Jazz electric, Crunch, Distorted or a simple synth. The amp sounds were made from your own Peavey 5150 amp captures and cab impulse responses. Jam has its own Guitar sound choice.', go: { settings: 'sound' } },
      { title: 'Vibrate on taps', text: 'Pads, keys, the tuner when a string is in tune, quiz answers, tap tempo and the rhythm trainer give a small buzz under your finger. It never buzzes while the mic is recording. Switch it off in Settings → Sound → Vibrate on taps.', go: { settings: 'sound' } },
      { title: 'The look (Psychedelic)', text: 'In the phone app the Psychedelic background stays still (easier on the battery and the eyes). On the web version it drifts slowly; Settings → Look → Moving colours turns that off.', go: { settings: 'look' } },
    ],
  },
  {
    id: 'menu', title: 'The menu and the poster', intro: 'Small things that make the screen yours.',
    items: [
      { title: 'Full screen', text: 'In the phone app, Settings → Look → Full screen hides the phone\'s own buttons, status bar and the Samsung taskbar, so nothing covers the bottom of the app. Swipe up from the bottom middle and they come back for a few seconds, then tuck away again. Without it, the app keeps its buttons clear of them by itself.', go: { settings: 'look' }, phoneOnly: true },
      { title: 'Tabs across the top, folds and the i buttons', text: 'Songs, Learn, Jam, Tools and Settings split into a few pages with a row of tabs across the top. Inside a page, extra parts fold into one line each (Looper, Famous progressions, Build your own practice tab …): tap the line to open or close it, and the app remembers. A small i next to a heading shows what it does.' },
      { title: 'Pinch to zoom', text: 'Anything small can be made bigger with two fingers: the tab, every fretboard (quizzes, Scales, Scales & chords), chord shapes, the hand shape, the circle of fifths, the practice calendar and the Jam chord cards. Drag with one finger to look around; the 1× button puts it back. Each place remembers its size.' },
      { title: 'Hide the menu', text: 'Tap « Hide at the bottom of the side menu (or ⌄ on the bottom bar), or swipe it away. A small tab stays on the left edge: tap it to slide the menu out, pick a section, and it tucks away again. Keep open puts it back for good.' },
      { title: 'The KGuitar poster', text: 'The little picture in the menu (and on Learn on phones) is the KGuitar poster: tap it to see it full screen, tap again to zoom in and drag around. Settings → Look can hide it.', go: { settings: 'look' } },
    ],
  },
  {
    id: 'keep', title: 'Keeping your progress', intro: 'Everything is stored on your phone or tablet.',
    items: [
      { title: 'Back up', text: 'Settings → Backup → Back up now, then pick Google Drive in the share menu. Restore from that file on a new phone or tablet to bring back your songs, streak and progress.', go: { settings: 'backup' } },
      { title: 'Reminders', text: 'Settings → You → Reminders sends a daily reminder at the time you choose, plus an optional late "streak saver". Days you\'ve already practised are skipped.', go: { settings: 'you' } },
      { title: 'What you use', text: 'Settings → You → What you use. KGuitar counts which screens, pages and buttons you open, on this phone only (nothing is sent anywhere). It shows your favourites, and after a month the things you haven\'t opened, so the app can be trimmed to how you really use it. "Start counting again" clears it.', go: { settings: 'you' } },
      { title: 'Day, Night and Psychedelic', text: 'Settings → Look. Psychedelic is the default: neon colours on deep purple with liquid colour drifting behind everything, and the KGuitar artwork all through the app: Brandy the chocolate lab and the other samurai dogs (every one with a guitar), dragon guitars, amp towers, oni suns and moons, mushrooms and waves. Each screen has its own picture at the top, and snippets of the art float behind the cards. The words always sit on dark cards so they stay easy to read. Your samurai picks the dog who greets you on finished songs, quizzes, celebrations and empty pages (or Mix it up for a different one each day). The art shows every picture: tap one to see it full screen, tap again to zoom, and use the arrows to step through them. The background holds still while KGuitar is listening to you, and Moving colours switches the motion off altogether (it also stops if the phone is set to reduce motion). Day is bright and clear; Night is dim and low-glare for practising in bed; "Match my phone" switches between them with your phone\'s dark mode.', go: { settings: 'look' } },
    ],
  },
  {
    id: 'tips', title: 'Tips for getting good', intro: 'What actually makes you better, fastest.',
    items: [
      { title: 'Little and often', text: '15 minutes every day beats 2 hours once a week. The streak and reminders are there to help with exactly that.' },
      { title: 'Slow and clean first', text: 'Play it right slowly, then speed up a little at a time. Use the speed trainer on the hard bars.' },
      { title: 'Loop the hard part', text: 'Don\'t replay the whole song to fix one bar. Loop just those bars until they\'re green.' },
      { title: 'Use your ears', text: 'Hum what you play, do a round of ear training most days, and play songs you love.' },
    ],
  },
]
